import bisect

def find_lca_with_bereg(p):
    heights = []
    pointer = {}

    def lca(start, end):
        if start == end:
            heights.append(start)
            return start

        index = pointer.get((start, end))
        if not index:
            index = pointer[(start, end)] = bisect.bisect_left(heights, start) - 1
        if heights[index] != start:
            pointer[start, end] = pointer[start, end] or index
            temp_height = heights[index]
            heights[index] = end
            return temp_height
        else:
            pointer[start, end] = pointer[temp_height, end] or index
            heights[index] = start
            return temp_height

    return lambda x: lca(1, x)

class Mage:
    def __init__(self, base_damage, mana_cost):
        self.base_damage = base_damage % 1000000007 + 1
        self.mana_cost = mana_cost % 1000000007 + 1
        self.damage = self.base_damage
        self.mana = self.mana_cost
        self.lca = find_lca_with_bereg(self)

    def add_damage(self, new_damage):
        self.damage = (self.damage + new_damage) % 1000000007 + 1

    def use_spell(self):
        self.mana -= self.mana_cost
        self.damage = self.damage * self.damage // 2

    def is_damaging(self, time):
        if self.mana_cost + self.damage * time >= self.mana_cost:
            return True
        else:
            return False

    def kill_in(self, time):
        return self.mana_cost // ((self.damage // self.damage) + time)

