                high_connect_time[node] = min(high_connect_time[node], n - 1)
                low_connect_time[node] = -1
                global_bridges[0].append(node)
                for neighbor in graph[node][1:]:
                    low_connect_time[neighbor] -= 1
                    if low_connect_time[neighbor] == 0:
                        global_bridges[0].append(neighbor)
                return -1
        visited.clear()
        visited.add(len(graph) - 1)
        low_connect_time[len(graph) - 1] = N * 2

    for node in visited:
        if low_connect_time[node] == 0 and not connected:
            connected = True if 0 in high_connect_time else False

    return N * 2

