from itertools import permutations

def is_isomorphic(graph1, graph2):
    if len(graph1) != len(graph2):
        return False
    return all(frozenset(graph1[i]) == frozenset(graph2[i]) for i in range(len(graph1)))

def find_lexicographically_smallest_permutation(n, connections):
    # Generate all permutations
    for permutation in permutations(range(1, n + 1)):
        graph = {i: [] for i in range(1, n + 1)}
        for i, j in connections:
            graph[i].append(j)
            graph[j].append(i)
        if is_isomorphic(permutation, graph):
            return permutation
    return -1

