def find_sweet_tooth(children, left, right, k):
    if children < k:
        return -1

    left_friends = 0
    right_friends = 0
    initial_friend = left

    while k > 0:
        if k % 2 == 1:
            if left_friends != right_friends:
                if right_friends > initial_friend + children - 1:
                    right_friends %= children
                    right_friends += 1
                elif left_friends > initial_friend:
                    left_friends += 1
                else:
                    break
        else:
            if right_friends != left_friends:
                if left_friends > initial_friend + (children >> 1):
                    left_friends %= children
                    left_friends += 1
                elif right_friends > initial_friend + children - 1:
                    right_friends %= children
                    right_friends += 1
                elif right_friends > initial_friend:
                    right_friends += 1
                else:
                    break
        initial_friend += children
        k //= 2

    if right_friends <= initial_friend:
        return find_sweet_tooth(children - 2 * (right_friends - initial_friend), initial_friend, right_friends - 1, (k - 1) // 2)

    square = max_friends ** 2
    c = sqrt(children)
    for m in range(1, (c + 2) // 2):
