import sys

def find_path(graph, start, end, path=None):
    if path is None:
        path = []
    path.append(start)

    if start == end:
        return path

    for neighbor in graph[start]:
        if neighbor not in path:
            new_path = find_path(graph, neighbor, end, path)
            if new_path is not None:
                return new_path

    path.remove(start)
    return None

def check_isomorphism(graph1, graph2):
    if sorted((v, list(map(int, e.split())) for e in graph1)) != sorted((v, list(map(int, e.split())) for e in graph2)):
        return False
    parent_dict = {v: None for v in graph1}
    stack = list(parent_dict.keys())

    while(stack):
        current = stack.pop()
        for neighbor in graph1[current]:
            if neighbor is parent_dict[current]:
                new_parent = current
            elif neighbor in parent_dict:
                new_parent = parent_dict[neighbor]
                break
        parent_dict[current] = new_parent
        stack.extend(graph1[current] + parent_dict[neighbor] for neighbor in graph1[current])

    return adjacency_list_representation(root_id) == parent_dict[parent_dict[root_id]] for root_id in parent_dict.keys()

def generate_permutation(n, graph):
    weights = [i+1 for i in range(n)] * 2
    for i in range(n-1):
        v, w = find_path(graph, weights[i], weights[i])+1+preferred_weights[(i+1)%n]
        weights[i] = w
    return weights

def preferred_weights(i):
    return (i%3)//2

def adjacency_list_representation(indices):
    permutation = '_'.join(str(index) for index in indices)
    return permutation

