def find_longest_nondegenerate(n, arr):
    # Initialize variables to keep track of counts and positions
    record_count = {}
    bucket_count = {}
    max_val = 0
    max_num = 0

    # Initialize scores for first pass
    for i in range(n):
        val = arr[i]
        bucket_count[val] = bucket_count.get(val, 0) + 1
        if bucket_count[val] == 1:
            max_val, max_num = val, i
        elif bucket_count[val] >= 2:
            bucket_count[val] = 0
        record_count[i] = bucket_count[val]

    # Handle last pass separately
    last_bucket_count = arr[:]
    for i in range(len(last_bucket_count)-1, -1, -1):
        val = last_bucket_count[i]
        bucket_count[val] = bucket_count.get(val, 0) + 1
        if bucket_count[val] == 1:
            max_val, max_num = val, i
        elif bucket_count[val] >= 2:
            bucket_count[val] = 0

    max_len = 0 
    # Find longest subarray where the max count is not unique
    for i in range(0, n-1):
        if record_count[i] == max_val:
            cur_len = i - max_num + 1
            if cur_len > max_len:
                max_len = cur_len

    return max_len

