def find_perfect_tree(n, edges):
    parent = {i: i for i in range(1, n + 1)}
    levels = [1] * (n + 1)
    max_level = 0
    for (u, v) in edges:
        if u > v:
            u, v = v, u
        if parent[u] != u:
            u = parent[u]
        if parent[v] != v:
            v = parent[v]
        if u < v:
            parent[v] = u
            levels[u] = max(levels[u], levels[v] + 1)
        max_level = max(max_level, levels[u])
        if levels[u] > max_level + 1:
            return ["-1"] * n
        if u > v:
            levels[v] = max(levels[v], levels[u])
    if "1" in levels:  # Including n
        return list(parent.values())
    else:
        return ["-1"]

