import sys

def generate_permutation(n, edges):
    # Create a graph from the input edges
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append(v)
        graph[v].append(u)

    # Initialize the result permutation
    result = []

    # Helper function to explore the graph
    def explore(u, parent=-1):
        result.append(u)
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                result.extend(explore(v, u))

    # Mark all vertices as not visited
    visited = [False] * (n + 1)
    for u in graph:
        if not visited[u]:
            explore(u)

    # Reshuffle the permutation to find the lexicographically smallest one
    result = result * (len(result) // n) * 2
    result.sort()
    return list(map(int, result))

