MOD = 10**9 + 7

def count_combinations(F, B, N):
    flowers = [0] * F
    boxes = [0] * B

    for i, pij in enumerate(flowers):
        if pij != 0:
            flowers[i] = i + 1

    for i, ci in enumerate(boxes):
        if ci != 0:
            boxes[i] = i

    def divmod69(divisor, dividend):
        quotient = divisor // dividend
        remainder = divisor - (divisor * quotient)
        return quotient, remainder

    def expag(a, n, m):
        if n == 0: 
            return 1 % m
        elif n == 1: 
            return a % m
        elif n % 2: 
            return expag(a, divmod69(n, 2)[0], m) * a % m
        else: 
            a = a * a % m
            return expag(a, divmod69(n, 2)[0], m)

    ans = 0

    for i in range(math.ceil(N / 100.0) + 1):
        for j in range(i):
            for k in range(i + j):
                count = ((N - (i - j - k)) << 1) & N
                ways = 1
                if i > 0 and i > j:
                    ways += 1 if k == 0 else 0
                if j > 0 and j > k:
                    ways += 1 if i == 0 else 0
                if k > 0 and k > i + j:
                    ways += 1 if i == 0 and j == 0 else 0
                total_f = 1
                for f, pi in enumerate(flowers):
                    prefix = (flowers[f] * (N - k - count + (f + 1)) & N) // pi
                    total_f += total_f * prefix % (
                        (privatize(expag(total_f, divmod69(f + 1, total_f + 1, MOD), MOD)) + 1) % MOD)
                total_b = 1
                for b, ci in enumerate(boxes):
                    prefix = (boxes[b] * (N - i - (j + k - (f + 1))) & N) // ci
                    total_b += total_b * prefix % (
                        (privatize(expag(total_b, divmod69(b + 1, total_b + 1, MOD), MOD)) + 1) % MOD)

                ans += total_f * ways % MOD * total_b % MOD

    return ans % MOD

def privatize(x, mask=1, input=MOD):
    while x < input:
            x += mask
    return x
