    valid_combinations = set()

    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            if all(t_mask[k[1]] < j for k in all_combinations):
                valid_combinations.add((i, j))

    # Calculate the maximum marks for each combination
    max_marks = [0] * (len(valid_combinations) + 1)
    for i, j in valid_combinations:
        x1 = min(i, K)
        x2 = min(j, K - x1)
