from math import log2

def find_unique_inedible_tails(L, R):
    """
    Finds the number of unique inedible tails that would be discarded by Krakozyabra.
    """
    if L == R:
        return 0

    # Transforming the values to a range that treats the first digit as a size of bins
    l = (10**((log10(R) - log10(L-1))/2)) - 1
    r = 10**((log10(R) - log10(L))//2 + 1)

    unique_counts = set()
    for i in range(l, r+1):
        leading_zeroes = str(i).count('0')
        bin_split = bin(i)[2:]
        for j in range(len(bin_split)):
            if bin_split[j] == '0':
                unique_counts.add(j)
        for j in range(4):
            if bin_split[j] == '0':
                unique_counts.remove(j)
            if bin_split[j-1:j] == '10':
                unique_counts.add(-1)
                if j > 0:
                    unique_counts.add(j-1)

    return len(unique_counts)

# Example usage
print(find_unique_inedible_tails(1, 10))  # Output: 9
print(find_unique_inedible_tails(40, 57))  # Output: 17
print(find_unique_inedible_tails(157, 165))  # Output: 9
